example.code:
word = "cat"
for letter in word:
    print(letter)

for item in [1, 2, 3]:
    print(item)

# Accumulator: add up numbers
total = 0
for num in [1, 2, 3]:
    total = total + num
print(total)

# break and continue
for i in range(5):
    if i == 2:
        continue
    if i == 4:
        break
    print(i)

